import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, float, uniform, time, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, Vector2 } = THREE;

  const group = new Group();
  group.name = 'pricing-title';

  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const ink = new Color(colors.ink ?? '#16161d');
  const paper = new Color(colors.paper ?? '#e8ecf2');
  const accent = new Color(colors.accent ?? '#ff2a38');
  const surface = new Color(colors.surface ?? '#0b0b10');

  // --- Engineered gradient backdrop plane (surface -> ink, vertical) ---
  const backdropGeo = new PlaneGeometry(7, 1.6);
  const gradMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const v = uv();
  const t = smoothstep(float(0.0), float(1.0), v.y);
  const baseCol = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r * 0.85, ink.g * 0.85, ink.b * 0.9),
    t
  );
  // Subtle grain via hash noise on uv
  const nx = fract(sin(v.x.mul(float(129.1)).add(v.y.mul(float(78.3))).mul(float(43758.5453))));
  const grain = nx.sub(float(0.5)).mul(float(0.04));
  gradMat.colorNode = baseCol.add(vec3(grain, grain, grain));
  const backdrop = new Mesh(backdropGeo, gradMat);
  backdrop.position.set(0, 0, -0.2);
  group.add(backdrop);

  // --- Accent rule line beneath the title ---
  const lineGeo = new PlaneGeometry(1.2, 0.025);
  const lineMat = new MeshBasicNodeMaterial({ color: accent, transparent: true, opacity: 0.95 });
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -0.62, -0.05);
  group.add(line);

  // --- Hero image asset (isolated, composites over gradient) ---
  let imageMesh = null;
  let imageMat = null;
  let imageGeo = null;
  if (config.imageUrl) {
    imageGeo = new PlaneGeometry(1.7, 1.7);
    imageMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, opacity: 0.9 });
    imageMesh = new Mesh(imageGeo, imageMat);
    imageMesh.position.set(2.55, 0.05, 0.0);
    group.add(imageMesh);
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (imageMat) {
        imageMat.map = tex;
        imageMat.needsUpdate = true;
      }
    });
  }

  // --- Text content: "Pricing" headline ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? (item.role === 'headline' ? 96 : 48);
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: '#e8ecf2',
      align: 'center',
      letterSpacingPx: fontSize * 0.01,
    });
    txt.position.set(-0.6, 0.04, 0.05);
    group.add(txt);
    textObjects.push(txt);
  }

  // --- Entrance: weighted-settle, no idle (static composition) ---
  const tl = gsap.timeline();
  group.scale.set(0.98, 0.98, 1);
  group.position.x = 0;
  tl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.fromTo(backdrop.material, { opacity: 0 }, { opacity: 1, duration: 0.7, ease: 'power2.out' }, 0);
  if (lineMat) tl.fromTo(lineMat, { opacity: 0 }, { opacity: 0.95, duration: 0.6, ease: 'power2.out' }, 0.2);
  textObjects.forEach((tObj, i) => {
    tl.fromTo(tObj.position, { y: 0.3 }, { y: 0.04, duration: 0.7, ease: 'power3.out' }, 0.1 + i * 0.05);
    tl.fromTo(tObj, { scale: 0.96 }, { scale: 1, duration: 0.7, ease: 'power3.out' }, 0.1 + i * 0.05);
  });

  const timelines = [tl];

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    backdropGeo.dispose();
    gradMat.dispose();
    lineGeo.dispose();
    lineMat.dispose();
    if (imageGeo) imageGeo.dispose();
    if (imageMat) imageMat.dispose();
    group.traverse((o) => {
      if (o.geometry && o.geometry !== backdropGeo && o.geometry !== lineGeo && o.geometry !== imageGeo) {
        o.geometry.dispose();
      }
      if (o.material && o.material !== gradMat && o.material !== lineMat && o.material !== imageMat) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
  };

  return group;
}
